CustomField.formula:
IF(CONTAINS(TEXT(Contract_Type__c), 'Value'),
    IF( ISNUMBER(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')),
        IF( VALUE(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')) > 31,
            'Yes',
            'No'
        ),
        'No'
    ),
    IF( ISNUMBER(SUBSTITUTE(TEXT(Storage_Discount__c),'%','')),
        IF( VALUE(SUBSTITUTE(TEXT(Storage_Discount__c),'%','')) > 56,
            'Yes',
            IF( ISNUMBER(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')),
                IF( VALUE(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')) > 56,
                    'Yes',
                    'No'
                ),
                'No'
            )
        ),
        IF( ISNUMBER(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')),
			IF( VALUE(SUBSTITUTE(TEXT( Services_Discount__c ),'%','')) > 56,
				'Yes',
				'No'
			),
			'No'
		)
    )
)
